python - <<'PY'
import sys,numpy as np
from PIL import Image
from scipy.ndimage import distance_transform_edt
sys.path.insert(0,'/app/output');import gen
from rcb_brush import Session
s=Session(instance='/app/instance.json',render=False)
base=[(-12,2),(6,-6),(-20,-6),(-12,-9),(-3,9),(-18,3),(-12,-10),(-9,-17),(6,-11),(6,-1),(9,-7),(-4,2),(1,1)]
gen.synthetic_preview(s,True,.70,8,True,False,base)
recs=s.strokes();masks=[]
for r in recs:
 full=np.zeros((1024,1024),bool);r0,c0=r['mask_bbox'];a=np.asarray(r['mask'])>=128;full[r0:r0+a.shape[0],c0:c0+a.shape[1]]=a;masks.append(full[180:850,230:810])
T=(np.asarray(Image.open('/app/target.png').convert('L'))<100)[180:850,230:810];tot=T.sum()
def shifted(a,dx,dy):return np.roll(a,(dy,dx),(0,1))
def score(us):
 p=np.zeros_like(T)
 for a,(dx,dy) in zip(masks,us):p|=shifted(a,dx,dy)
 inter=np.count_nonzero(p&T);return inter/(p.sum()+tot-inter),int(p.sum()),int(inter)
cur=[(0,0)]*13;print('start',score(cur),flush=True)
for rad in [7,3,1]:
 for i in range(13):
  best=score(cur)[0];bi=cur[i]
  others=np.zeros_like(T)
  for j,(a,(dx,dy)) in enumerate(zip(masks,cur)):
   if j!=i:others|=shifted(a,dx,dy)
  for dy in range(cur[i][1]-rad,cur[i][1]+rad+1):
   for dx in range(cur[i][0]-rad,cur[i][0]+rad+1):
    cand=others|shifted(masks[i],dx,dy);inter=np.count_nonzero(cand&T);val=inter/(cand.sum()+tot-inter)
    if val>best+1e-9:best=val;bi=(dx,dy)
  cur[i]=bi
  print('r',rad,'i',i+1,'inc',bi,'actual',(base[i][0]+bi[0],base[i][1]+bi[1]),'iou',round(score(cur)[0],4),flush=True)
 print('pass',rad,score(cur),flush=True)
print('INCREMENTS',cur);print('ACTUAL',[(a+c,b+d) for (a,b),(c,d) in zip(base,cur)])
from PIL import Image
p=np.zeros_like(T)
for m,sh in zip(masks,cur):p|=shifted(m,*sh)
full=np.zeros((1024,1024),np.uint8);full[180:850,230:810]=p
Image.fromarray(full*255).save('/app/output/coord_opt.png')
s.close()
